import{_ as t}from"./chunks/settings-robot.pc.en.DW3gmNOs.js";import{_ as o,o as a,c as d,a5 as s}from"./chunks/framework.D47SInms.js";const n="/RBQ/nightly/images/app/settings-app.pc.en.png",b=JSON.parse('{"title":"Settings","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/settings.md","filePath":"manual/gui/settings.md","lastUpdated":1791600043000}'),r={name:"manual/gui/settings.md"};function i(c,e,h,l,p,g){return a(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Open settings with the <code>Settings</code> tile on the hub. All sections sit as chips across the top — icons only on a phone — in two groups. The title reads <code>Settings</code> with the robot&#39;s name and serial, the device and the app version.</p><ul><li><strong>Robot sections</strong> belong to the selected robot: <code>Power</code>, <code>Payload setup</code>. They open even without a robot, but anything that acts on the robot needs it connected. While the in-app simulator is selected they are dimmed.</li><li><strong>App sections</strong> belong to this device: <code>Gamepad</code>, <code>App settings</code>. They always open.</li></ul><p>On every settings screen the logo at the top left returns to the hub, and the gamepad button next to it goes straight to the control screen. That button works only while a robot is connected or the sim is running.</p><ul><li>Connecting to a robot is done from the robot list on the hub — see <a href="/RBQ/nightly/manual/gui/connection.html">Connection</a>.</li><li><code>Gamepad</code> is covered in <a href="/RBQ/nightly/manual/gui/gamepad.html">Gamepad</a>.</li><li><code>Calibration</code>, <code>Robot Check</code> and <code>Software update</code> are on the <a href="/RBQ/nightly/manual/gui/maintenance.html">Maintenance</a> screen.</li></ul><p>This page covers <code>Power</code>, <code>Payload setup</code> and <code>App settings</code>. Operators can use all of them, and rows that need developer mode are marked.</p><h2 id="power" tabindex="-1">Power <a class="header-anchor" href="#power" aria-label="Permalink to &quot;Power {#power}&quot;">​</a></h2><p>This section switches the auxiliary rails you use day to day. The toggles show the actual PDU state the robot reports, so a change can take about a second to show up. Until the first rail state arrives, the toggles stay disabled.</p><p><strong>12 V toggles</strong> (one tap): <code>Speaker amp (12V)</code>, <code>CCTV (12V)</code>, <code>Thermal (12V)</code>, <code>IR LED (12V)</code>.</p><p><strong>48 V rails</strong> (two-step): <code>ARM · ADDON (48V)</code> and <code>EXTERN (48V)</code> each show the live voltage and a <code>Turn off</code> / <code>Turn on</code> button. Pressing it opens <code>Turn this off?</code> or <code>Turn this on?</code>. Confirm to switch.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>ARM · ADDON (48V)</code> is one PDU port shared by the arm and the add-on. Turning it off also cuts arm power — make sure the arm is stopped first.</p></div><p>Camera, comm, Vision PC, and LEGS (48 V) power, along with LiDAR and system reboot, are not here — switching any of them off breaks the connection or drops the robot. They live in <a href="/RBQ/nightly/manual/gui/maintenance.html">Maintenance</a> (developer mode).</p><p>On CAN-FD robots this section lists ports instead of rails: <code>CCTV (12V · LAN2)</code>, <code>Thermal · PTZ (12V · LAN3)</code>, <code>Front 12V (IR LED)</code>, <code>Rear 12V (IR LED)</code>, <code>Speaker amp</code> (one tap) and <code>ARM · ADDON (48V)</code> (two-step). Each row shows the live state, voltage and current, and stays locked until the port state has been received.</p><p>CAN-FD robots also show <code>Bottom status LEDs (IF board)</code>, one row for each of the two status LEDs under the body: <code>Right LED</code> and <code>Left LED</code>. A row shows the LED&#39;s current setting, its power in W, and a swatch of the color it actually puts out. <code>Settings</code> opens a dialog filled with what the robot reports. Under <code>Recommended</code>, pick <code>Keep off</code> or one of the values approved for RBQ; the dialog also shows the <code>Current setting</code>. Check <code>Apply the same to the other LED</code> to set both LEDs at once. <code>Apply</code> sends the setting and reads it back from the robot — <code>Applied — matches the robot</code> means the LED took it. <code>Reload</code> fills the dialog again from the robot.</p><p>The IF board limits LED power by itself (20 W instant, 10.5 W sustained), so a bright setting can come out dimmer than you set, and the row then shows <code>Limited</code>. When the robot cannot be read, the row shows <code>No reading</code> together with the last value this device read or sent. Right after the IF board restarts, the rows show <code>Not set — the IF board restarted and hasn&#39;t received a setting yet</code> until a setting reaches it. If the robot software is older than this feature, the rows read <code>The robot software doesn&#39;t have this feature yet. An update is needed</code>. If the IF board firmware is older than these LEDs need, the rows instead give the board&#39;s version and the minimum, for example <code>IF firmware update needed — it is 261003 and must be 261005 or later</code>, and <code>Apply</code> stays disabled until the board is updated.</p><blockquote><p><strong>What developer mode adds here</strong> is collected on <a href="/RBQ/nightly/manual/gui/developer-mode.html#what-changes">Developer mode</a>.</p></blockquote><h2 id="robot-parameters" tabindex="-1">Payload setup <a class="header-anchor" href="#robot-parameters" aria-label="Permalink to &quot;Payload setup {#robot-parameters}&quot;">​</a></h2><p><img src="'+t+'" alt="Robot parameters section"></p><p><code>Payload Configuration</code> describes what is mounted on the robot so the walking dynamics can account for it.</p><ol><li>The robot reports 13 payload slots. Check a slot to mark it as mounted and enter its mass and center of mass (X, Y, Z).</li><li>The footer shows the total mass and combined center of mass, and warns when the total exceeds the limit.</li><li>Press <code>Set Payload</code> and confirm with <code>Apply</code> (<code>Get</code> re-reads the slots from the robot and discards your edits). The confirmation shows the number of mounted slots and the totals; unchecked slots are sent with mass 0. The new values reach the walking dynamics right away, ramped in over one to two seconds.</li></ol><p><code>Help</code> expands a short guide above the table. Robots without the payload slot API show a notice asking for a robot software update instead.</p><h2 id="app-settings" tabindex="-1">App settings <a class="header-anchor" href="#app-settings" aria-label="Permalink to &quot;App settings&quot;">​</a></h2><p><img src="'+n+'" alt="App settings section"></p><p>These settings belong to the app, not the robot.</p><table tabindex="0"><thead><tr><th>Row</th><th>Options</th></tr></thead><tbody><tr><td><code>Theme</code></td><td><code>Dark</code> / <code>Light</code></td></tr><tr><td><code>Language / 언어</code></td><td><code>Korean</code> / <code>English</code> — applies immediately</td></tr><tr><td><code>Joystick sensitivity</code></td><td>Slider — input response curve</td></tr><tr><td><code>Keep screen on</code></td><td>Toggle — keeps the screen awake while controlling</td></tr><tr><td><code>Deadzone</code></td><td>Slider — center range ignored by the joystick</td></tr><tr><td><code>Gyro widget</code></td><td>Toggle — roll/pitch attitude display</td></tr><tr><td><code>Fullscreen</code></td><td>Toggle — browser only</td></tr><tr><td><code>Low-signal warning</code></td><td>Toggle — top warning banner when Wi-Fi signal drops below <code>Warning threshold</code> (slider, shown while enabled)</td></tr><tr><td><code>Warning beep (Notify BEEP)</code></td><td>Toggle — short beep on warnings (web only)</td></tr><tr><td><code>Low battery beep</code></td><td>Toggle — beeps when the robot battery is low; <code>Warning beep (Notify BEEP)</code> must be on (web only)</td></tr><tr><td><code>UI scale</code></td><td>Desktop app only — <code>Auto</code>, 100 % to 200 %</td></tr></tbody></table><h3 id="developer-mode" tabindex="-1">Developer mode <a class="header-anchor" href="#developer-mode" aria-label="Permalink to &quot;Developer mode {#developer-mode}&quot;">​</a></h3><p>The <code>Developer mode</code> toggle is in the profile menu — the round button at the top right. As a guest, turn on <code>Developer mode</code> and enter the password. Turning it off puts you back at the operator level. While you are logged in with an access code (<code>Log in with access code</code> in the same menu) the toggle is not shown, because the account decides the level.</p><p>Developer mode adds the developer sections of <code>Maintenance</code>, the developer rows above, and the <code>Position control</code> group in the <code>Select motion</code> grid.</p>',28)])])}const w=o(r,[["render",i]]);export{b as __pageData,w as default};
